PROGRAM ST_C05_KVALITETSLOOP
VAR
    stegPrd     : INT := 1;
    stegMrg     : INT := 0;
    tmrCam      : TON;
    tmrPsh      : TON;
    tmrMrg      : TON;
    rwkPending  : BOOL := FALSE;
    trigRwk     : R_TRIG;
    godkanda    : INT := 0;
    utskjutna   : INT := 0;
    kvitterade  : INT := 0;
    koLangd     : INT := 0;
    xRaknefel   : BOOL := FALSE;
END_VAR

trigRwk(CLK := ST440_RWK_DONE);
IF trigRwk.Q THEN
    rwkPending := TRUE;
    kvitterade := kvitterade + 1;
END_IF;

(* Omarbetningskon som styrningen SJALV kan rakna ut: utskjutna kartor minus
   kvitterade. Klamd vid noll darfor att operatoren kan kvittera kartor som
   skjutits ut fore matstart. *)
koLangd := utskjutna - kvitterade;
IF koLangd < 0 THEN
    koLangd := 0;
END_IF;

(* De tre raknarna i kartan ar scenens, inte styrningens, och de mats mot
   styrningens egen bokforing. Alla tre far ligga hogst EN karta efter - den
   som ar pa vag - men aldrig fore: en raknare som gar fortare an linjen ar
   ett rakningsfel (scenarierna cnt_hog, rwk_hog), och en som star still
   medan kartor lamnar linjen ar ett givarfel (cnt_lag, rwk_lag, que_lag).
   Taket 10 pa kon ar omarbetningsplatsens tio platser (scenariot que_hog:
   14 kartor i kon). Utan trovardig rakning startas ingen ny karta: ett
   kapacitetsmal som mats med en trasig raknare ar inget mal, och en ko som
   vaxit forbi platserna far inte fyllas pa. *)
xRaknefel := (ST430_PRD_CNT > godkanda)   OR (ST430_PRD_CNT < godkanda - 1)
          OR (ST440_RWK_CNT > kvitterade) OR (ST440_RWK_CNT < kvitterade - 1)
          OR (ST440_RWK_QUE > koLangd)    OR (ST440_RWK_QUE < koLangd - 1)
          OR (ST440_RWK_QUE > 10);

tmrCam(IN := (stegPrd = 2), PT := T#300ms);
tmrPsh(IN := (stegPrd = 3), PT := T#500ms);
tmrMrg(IN := (stegMrg = 2), PT := T#1000ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    ST430_PRD_START := FALSE;
    ST430_PSH_RWK   := FALSE;
    ST430_MRG_OPEN  := FALSE;
    ST430_CAM_TRIG  := FALSE;
    stegPrd := 0;
    stegMrg := 0;
    rwkPending := FALSE;
ELSE
    IF stegPrd = 0 THEN
        stegPrd := 1;
    END_IF;

    CASE stegPrd OF
        1:
            ST430_PRD_START := NOT xRaknefel;
            ST430_CAM_TRIG  := FALSE;
            ST430_PSH_RWK   := FALSE;
            IF ST430_PRD_DONE THEN
                ST430_PRD_START := FALSE;
                stegPrd := 2;
            END_IF;
        2:
            ST430_CAM_TRIG := TRUE;
            IF ST430_CAM_OK THEN
                ST430_CAM_TRIG := FALSE;
                godkanda := godkanda + 1;
                stegPrd := 4;
            ELSIF tmrCam.Q THEN
                ST430_CAM_TRIG := FALSE;
                ST430_PSH_RWK  := TRUE;
                utskjutna := utskjutna + 1;
                stegPrd := 3;
            END_IF;
        3:
            IF tmrPsh.Q THEN
                ST430_PSH_RWK := FALSE;
                stegPrd := 4;
            END_IF;
        4:
            ST430_PRD_START := FALSE;
            ST430_CAM_TRIG  := FALSE;
            ST430_PSH_RWK   := FALSE;
    END_CASE;

    CASE stegMrg OF
        0:
            ST430_MRG_OPEN := FALSE;
            IF rwkPending THEN
                stegMrg := 1;
            END_IF;
        1:
            IF ST430_MRG_FREE AND rwkPending THEN
                ST430_MRG_OPEN := TRUE;
                rwkPending := FALSE;
                stegMrg := 2;
            ELSE
                ST430_MRG_OPEN := FALSE;
            END_IF;
        2:
            IF tmrMrg.Q THEN
                ST430_MRG_OPEN := FALSE;
                stegMrg := 0;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

